/// Recorded whether or not an agent was free, so the enquiries nobody answered\n/// are exactly the ones that can be followed up.\nmodel Lead {\n  id        String   @id @default(cuid())\n  companyId String\n  name      String\n  email     String\n  phone     String\n  /// Branch chosen most recently. Kept nullable so removing a branch does not\n  /// destroy the lead.\n  branchId  String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  company   Company   @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  branch    Branch?   @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  /// One row per time they got in touch. Counts are derived from these rather\n  /// than denormalised onto the lead, so they cannot drift.\n  enquiries Enquiry[]\n\n  @@unique([companyId, email])\n  @@index([companyId, updatedAt])\n}\n\n/// A single approach from a lead: one submission of the pre-chat form.\n///\n/// Keeping every attempt, rather than only a counter on Lead, is what makes the\n/// history readable over time — when someone got in touch, which branch they\n/// wanted, and whether anyone was there to answer.\nmodel Enquiry {\n  id             String   @id @default(cuid())\n  leadId         String\n  branchId       String?\n  /// The chat that opened, when one did. Null for unanswered enquiries.\n  conversationId String?\n  /// False when nobody in that branch was online for this attempt.\n  answered       Boolean\n  createdAt      DateTime @default(now())\n\n  lead         Lead          @relation(fields: [leadId], references: [id], onDelete: Cascade)\n  branch       Branch?       @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  conversation Conversation? @relation(fields: [conversationId], references: [id], onDelete: SetNull)\n\n  @@index([leadId, createdAt])\n  @@index([branchId, createdAt])\n  @@index([answered, createdAt])\n}\n\nmodel Visitor {\n  id        String   @id\n  name      String\